 * LOD aggregate), or a virtual same-size cell carved from a coarser homogeneous leaf.
 */
public @NotNull Branch getAtLod(@NotNull BlockPos pos, int lodSize) {
    int lod = Math.max(1, lodSize);
    if (size < lod) {
        return this;
    }
    if (size == lod) {
        return this;
