			direction,
			FrustumLod.BASE_FOOTPRINT,
			PrecomputedConfig.pConfig.frustumGrowthPerBlock,
			BeamBudget.full()
	);
	for (BeamVisitRecorder.VisitedBox visit : BeamVisitRecorder.collectAlongBeam(
